#!/usr/bin/env node
/**
 * The token-drift gate.
 *
 * `ui/tokens/tokens.css` and `ui/tokens/tokens.ts` are generated by
 * `cargo run -p xtask -- tokens` from `docs/client-platform/data/tokens.json` and are never
 * hand-edited. `xtask/tests/tokens.rs` proves they are *derived* from the source and
 * `mjx-tokens`'s `artefacts_agree` suite proves the three artefacts agree with each other — but
 * both of those are Rust, and a `ui/` contributor who edits a hex value in `tokens.css` to see
 * what it looks like will not run either. So the TypeScript half of the pipeline carries its own
 * gate, and it runs with no dependency beyond Node: the whole point is that it cannot be skipped
 * because a toolchain is missing.
 *
 * ## What it checks, and what it deliberately does not
 *
 * Three legs, none of which re-implements the generator's value *formatting*:
 *
 * 1. **Coverage.** Every token in the source has a custom property in the CSS, a leaf in the TS
 *    `tokens` object, and a row in the TS `customProperties` table — and neither artefact carries
 *    anything the source does not declare. Names are derived here from first principles
 *    (`--` + path joined with `-`; camel-cased segments joined with `.`), exactly as
 *    `xtask/src/codegen/tokens/model.rs` states them.
 * 2. **Cross-artefact agreement.** For every token, the CSS declaration and the TS constant carry
 *    the same value. A hand-edit to one file and not the other dies here.
 * 3. **Scalar values against the source.** Where the source `$value` is a string or a number —
 *    every colour, every dimension, every duration, every weight, every line height — the emitted
 *    value must equal it exactly, after alias resolution. A hand-edit to *both* artefacts
 *    consistently still dies here.
 *
 * The composite values — font stacks, cubic-béziers and shadows — are checked *structurally*
 * (every component present, béziers parsed back to numbers and compared) rather than by
 * re-rendering them. Re-rendering would mean re-deciding, in JavaScript, questions the generator
 * has already decided (does a zero spread appear in the shadow? is a single-word family quoted?),
 * and a second guess at a formatting rule is a false gate rather than a second opinion.
 *
 * ## The scheme layer
 *
 * `tokens.css` ends with three rules that alias `--theme-*` and `--document-*` onto one scheme.
 * Those declarations have `var(...)` values, are not tokens, and are checked as a fourth leg: each
 * one must point at a property the source declares, both schemes must carry the same member names,
 * and every member must have an alias.
 */

import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const uiRoot = resolve(import.meta.dirname, '..');
const repoRoot = resolve(uiRoot, '..');
const sourcePath = resolve(repoRoot, 'docs/client-platform/data/tokens.json');
const cssPath = resolve(uiRoot, 'tokens/tokens.css');
const tsPath = resolve(uiRoot, 'tokens/tokens.ts');

/** @type {string[]} */
const failures = [];

/** @param {string} message */
function fail(message) {
  failures.push(message);
}

// ── The source ────────────────────────────────────────────────────────────────

/** @typedef {{ path: string[]; value: unknown }} SourceToken */

const source = JSON.parse(readFileSync(sourcePath, 'utf8'));

/** @type {SourceToken[]} */
const sourceTokens = [];

/**
 * @param {unknown} node
 * @param {string[]} path
 */
function walk(node, path) {
  if (typeof node !== 'object' || node === null) return;
  const record = /** @type {Record<string, unknown>} */ (node);
  if ('$value' in record) {
    sourceTokens.push({ path, value: record.$value });
    return;
  }
  for (const [key, child] of Object.entries(record)) {
    if (key.startsWith('$')) continue;
    walk(child, [...path, key]);
  }
}

for (const [key, value] of Object.entries(source)) {
  if (key.startsWith('$')) continue;
  walk(value, [key]);
}

if (sourceTokens.length === 0) fail(`${sourcePath} declared no tokens at all.`);

/** Dotted path exactly as the source writes it, for alias resolution. */
const byDottedSourcePath = new Map(sourceTokens.map((token) => [token.path.join('.'), token]));

/**
 * Resolve `{a.b}` references transitively. The source uses them for the whole light scheme and for
 * most of the document surface, so without this the third leg would check almost nothing.
 *
 * @param {unknown} value
 * @param {string[]} seen
 * @returns {unknown}
 */
function resolveAlias(value, seen = []) {
  if (typeof value !== 'string') return value;
  const match = /^\{([^}]+)\}$/.exec(value);
  if (match === null) return value;
  const target = match[1];
  if (seen.includes(target)) {
    fail(`alias cycle in the source: ${[...seen, target].join(' -> ')}`);
    return value;
  }
  const token = byDottedSourcePath.get(target);
  if (token === undefined) {
    fail(`the source aliases {${target}}, which no token declares.`);
    return value;
  }
  return resolveAlias(token.value, [...seen, target]);
}

// ── The naming rules, from xtask/src/codegen/tokens/model.rs ──────────────────

/** @param {string[]} path */
const customPropertyOf = (path) => `--${path.join('-')}`;

/** @param {string} segment */
const typescriptProperty = (segment) =>
  segment.replace(/-([a-z0-9])/g, (_, character) => character.toUpperCase());

/** @param {string[]} path */
const typescriptPathOf = (path) => path.map(typescriptProperty).join('.');

// ── The CSS artefact ──────────────────────────────────────────────────────────

const css = readFileSync(cssPath, 'utf8');
// Strip comments before scanning: the generated file documents every token above it, and a hex
// value inside a comment is not a declaration.
const cssWithoutComments = css.replace(/\/\*[\s\S]*?\*\//g, '');

/** @type {Map<string, string>} */
const cssValues = new Map();
/**
 * Alias name → every property it is pointed at, across the three scheme rules.
 *
 * The scheme layer declares each alias **three** times — the light default, the
 * `prefers-color-scheme: dark` rule, and the explicit `:root[data-theme="dark"]` rule — and the
 * three do not agree, which is the whole point: one names the light member and two name the dark
 * one. So this is a multimap, and leg 4 checks the *set* rather than a single value.
 *
 * @type {Map<string, Set<string>>}
 */
const cssAliases = new Map();

for (const match of cssWithoutComments.matchAll(/(--[a-z0-9-]+)\s*:\s*([^;]+);/g)) {
  const [, name, raw] = match;
  const value = raw.trim();
  const alias = /^var\((--[a-z0-9-]+)\)$/.exec(value);
  if (alias !== null) {
    const targets = cssAliases.get(name) ?? new Set();
    targets.add(alias[1]);
    cssAliases.set(name, targets);
  } else {
    if (cssValues.has(name)) fail(`${name} is declared twice in tokens.css.`);
    cssValues.set(name, value);
  }
}

if (cssValues.size === 0) fail('tokens.css declared no concrete custom properties.');

// ── The TypeScript artefact ───────────────────────────────────────────────────

const { tokens, customProperties } = await import(pathToFileURL(tsPath).href);

/**
 * @param {string} path
 * @returns {unknown}
 */
function readTypescriptPath(path) {
  /** @type {unknown} */
  let cursor = tokens;
  for (const segment of path.split('.')) {
    if (typeof cursor !== 'object' || cursor === null || !(segment in cursor)) return undefined;
    cursor = /** @type {Record<string, unknown>} */ (cursor)[segment];
  }
  return cursor;
}

/**
 * Every leaf of the TS `tokens` object, as a dotted path — so an artefact carrying a token the
 * source no longer declares is caught rather than ignored.
 *
 * @param {unknown} node
 * @param {string[]} path
 * @param {string[]} out
 */
function collectLeaves(node, path, out) {
  if (typeof node !== 'object' || node === null) {
    out.push(path.join('.'));
    return;
  }
  for (const [key, child] of Object.entries(node)) collectLeaves(child, [...path, key], out);
}

/** @type {string[]} */
const typescriptLeaves = [];
collectLeaves(tokens, [], typescriptLeaves);

// ── Leg 1 · coverage, and legs 2 and 3 beside it ─────────────────────────────

/** @type {Set<string>} */
const claimedCustomProperties = new Set();
/** @type {Set<string>} */
const claimedTypescriptPaths = new Set();

for (const token of sourceTokens) {
  const property = customPropertyOf(token.path);
  const typescriptPath = typescriptPathOf(token.path);
  claimedCustomProperties.add(property);
  claimedTypescriptPaths.add(typescriptPath);

  const cssValue = cssValues.get(property);
  if (cssValue === undefined) {
    fail(`tokens.css is missing ${property} (source token ${token.path.join('.')}).`);
    continue;
  }

  const typescriptValue = readTypescriptPath(typescriptPath);
  if (typescriptValue === undefined) {
    fail(`tokens.ts is missing ${typescriptPath} (source token ${token.path.join('.')}).`);
    continue;
  }

  const mapped = customProperties[typescriptPath];
  if (mapped !== property) {
    fail(
      `tokens.ts customProperties['${typescriptPath}'] is ${JSON.stringify(mapped)}, ` +
        `but the token's custom property is ${property}.`,
    );
  }

  // Leg 2 — the two artefacts must agree. Numbers reach CSS as their decimal spelling, which is
  // what String() produces for every numeric token in this source.
  if (String(typescriptValue) !== cssValue) {
    fail(
      `${token.path.join('.')} disagrees between the artefacts: ` +
        `tokens.css says ${JSON.stringify(cssValue)}, tokens.ts says ${JSON.stringify(String(typescriptValue))}.`,
    );
  }

  // Leg 3 — and both must still say what the source says.
  checkAgainstSource(token, cssValue);
}

/**
 * @param {SourceToken} token
 * @param {string} emitted
 */
function checkAgainstSource(token, emitted) {
  const where = token.path.join('.');
  const value = resolveAlias(token.value);

  if (typeof value === 'string' || typeof value === 'number') {
    if (String(value) !== emitted) {
      fail(
        `${where} is ${JSON.stringify(String(value))} in the source but ` +
          `${JSON.stringify(emitted)} in the artefacts.`,
      );
    }
    return;
  }

  if (Array.isArray(value) && value.every((entry) => typeof entry === 'number')) {
    // A cubic-bézier. Parsed back to numbers and compared, so the check is exact without
    // re-deciding how many spaces the generator puts after a comma.
    const match = /^cubic-bezier\(([^)]*)\)$/.exec(emitted);
    if (match === null) {
      fail(`${where} is a bézier in the source but the artefacts emit ${JSON.stringify(emitted)}.`);
      return;
    }
    const emittedNumbers = match[1].split(',').map((part) => Number(part.trim()));
    if (
      emittedNumbers.length !== value.length ||
      emittedNumbers.some((number, index) => number !== value[index])
    ) {
      fail(`${where} is [${value.join(', ')}] in the source but ${JSON.stringify(emitted)} emitted.`);
    }
    return;
  }

  if (Array.isArray(value)) {
    // A font stack. Checked by containment and by order: the quoting rule is the generator's.
    let cursor = 0;
    for (const family of value) {
      const at = emitted.indexOf(String(family), cursor);
      if (at < 0) {
        fail(`${where} omits the family ${JSON.stringify(family)} the source declares.`);
        return;
      }
      cursor = at + String(family).length;
    }
    return;
  }

  if (typeof value === 'object' && value !== null) {
    // A shadow. Every component the source names must appear, and the colour must be last —
    // whether a zero spread is written is the generator's decision and is not second-guessed here.
    const shadow = /** @type {Record<string, string>} */ (value);
    for (const component of ['offsetX', 'offsetY', 'blur', 'color']) {
      const part = shadow[component];
      if (part !== undefined && !emitted.includes(part)) {
        fail(`${where} omits its ${component} ${JSON.stringify(part)}; emitted ${JSON.stringify(emitted)}.`);
      }
    }
    if (typeof shadow.color === 'string' && !emitted.trimEnd().endsWith(shadow.color)) {
      fail(`${where} does not end with its colour ${JSON.stringify(shadow.color)}.`);
    }
    return;
  }

  fail(`${where} has a source value this check does not understand: ${JSON.stringify(value)}.`);
}

for (const property of cssValues.keys()) {
  if (!claimedCustomProperties.has(property)) {
    fail(`tokens.css declares ${property}, which no source token claims.`);
  }
}

for (const leaf of typescriptLeaves) {
  if (!claimedTypescriptPaths.has(leaf)) {
    fail(`tokens.ts declares ${leaf}, which no source token claims.`);
  }
}

for (const key of Object.keys(customProperties)) {
  if (!claimedTypescriptPaths.has(key)) {
    fail(`tokens.ts customProperties declares ${key}, which no source token claims.`);
  }
}

// ── Leg 4 · the scheme layer ─────────────────────────────────────────────────

/** @type {Map<string, Set<string>>} */
const schemeMembers = new Map();
for (const token of sourceTokens) {
  if (token.path.length !== 3) continue;
  const [group, scheme, member] = token.path;
  if (group !== 'theme' && group !== 'document') continue;
  const key = `${group}.${scheme}`;
  if (!schemeMembers.has(key)) schemeMembers.set(key, new Set());
  schemeMembers.get(key)?.add(member);
}

for (const group of ['theme', 'document']) {
  const light = schemeMembers.get(`${group}.light`);
  const dark = schemeMembers.get(`${group}.dark`);
  if (light === undefined || dark === undefined) {
    fail(`the source does not declare both schemes for ${group}.`);
    continue;
  }
  for (const member of light) {
    if (!dark.has(member)) fail(`${group}.light.${member} has no dark counterpart.`);
    const alias = `--${group}-${member}`;
    const targets = cssAliases.get(alias);
    if (targets === undefined) {
      fail(`tokens.css has no scheme alias ${alias}; a component would have to name a scheme.`);
      continue;
    }
    // Both schemes must be reachable through the same alias. An alias that only ever pointed at
    // one of them would leave a component permanently in that scheme, which is exactly the defect
    // the scheme layer exists to prevent and is invisible until someone switches theme.
    for (const scheme of ['light', 'dark']) {
      const expected = `--${group}-${scheme}-${member}`;
      if (!targets.has(expected)) {
        fail(
          `the scheme alias ${alias} never points at ${expected}; the ${scheme} scheme is ` +
            'unreachable through it.',
        );
      }
    }
  }
  for (const member of dark) {
    if (!light.has(member)) fail(`${group}.dark.${member} has no light counterpart.`);
  }
}

for (const [alias, targets] of cssAliases) {
  for (const target of targets) {
    if (!cssValues.has(target)) {
      fail(`the scheme alias ${alias} points at ${target}, which tokens.css does not declare.`);
    }
  }
}

// ── Verdict ──────────────────────────────────────────────────────────────────

if (failures.length > 0) {
  console.error(
    `ui/tokens is out of step with docs/client-platform/data/tokens.json — ${failures.length} disagreement(s).\n` +
      'The two files under ui/tokens/ are GENERATED. Do not edit them; edit the source and run\n' +
      '  cargo run -p xtask -- tokens\n',
  );
  for (const failure of failures) console.error(`  · ${failure}`);
  process.exit(1);
}

console.log(
  `ui/tokens agrees with the source: ${sourceTokens.length} tokens, ` +
    `${cssValues.size} custom properties, ${cssAliases.size} scheme aliases.`,
);
